import { GameLayout, GameSession, SessionSave } from './GameSession';
import { KNOWN_PROGRESS_CONTRACT } from './KnownProgressContract';

export interface ProgressStorage {
  get(key: string): unknown;
  set(key: string, value: SessionSave): void;
}
export interface ProgressRestore {
  restored: boolean;
  migratedFrom: 1 | 2 | null;
  errors: string[];
}
const contract = (layout: GameLayout): string => JSON.stringify({
  sceneId: layout.sceneId,
  geoBlocks: [...layout.geoBlocks].sort((a, b) => a.blockOrder - b.blockOrder)
    .map(b => ({ blockId: b.blockId, blockOrder: b.blockOrder })),
  stickers: [...layout.stickers].sort((a, b) => a.stickerId < b.stickerId ? -1 : a.stickerId > b.stickerId ? 1 : 0)
    .map(s => ({ stickerId: s.stickerId, geoBlock: s.geoBlock, areaLevel: s.areaLevel,
      dependsOn: [...(s.dependsOn ?? [])].sort(), assemblyStep: s.assemblyStep, blockAssemblyStep: s.blockAssemblyStep })),
});

/** Only the reviewed 1/2 → 3 upgrade, including L026's chair support correction,
 * is eligible. No layout/editor state or invalid placement prefix migrates. */
export function restoreKnownProgress(session: GameSession, layout: GameLayout, storage: ProgressStorage,
  keyForRevision: (revision: string | number) => string): ProgressRestore {
  const errors: string[] = [];
  const current = storage.get(keyForRevision(layout.layoutRevision));
  if (current !== null && current !== undefined && current !== '') {
    const result = session.restore(current);
    return { restored: result.ok, migratedFrom: null, errors: result.errors };
  }
  if (layout.sceneId !== 'fragrance-pearl' || layout.layoutRevision !== 3
    || contract(layout) !== KNOWN_PROGRESS_CONTRACT) return { restored: false, migratedFrom: null, errors };
  for (const revision of [2, 1] as const) {
    const old = storage.get(keyForRevision(revision));
    if (!old || typeof old !== 'object' || Array.isArray(old)) continue;
    const save = old as Partial<SessionSave>;
    if (save.schemaVersion !== 'sticker-session-v1' || save.sceneId !== layout.sceneId || save.layoutRevision !== revision) {
      errors.push(`revision ${revision} save identity differs`); continue;
    }
    // GameSession validates IDs, duplicates, stage/dependency prefix and transition
    // state atomically against the new canonical layout before any storage write.
    const candidate = { ...save, layoutRevision: layout.layoutRevision };
    const outcome = session.restore(candidate);
    if (!outcome.ok) { errors.push(...outcome.errors.map(e => `revision ${revision}: ${e}`)); continue; }
    storage.set(keyForRevision(layout.layoutRevision), session.exportSave());
    return { restored: true, migratedFrom: revision, errors: [] };
  }
  return { restored: false, migratedFrom: null, errors };
}
