/** Gameplay validation alone is insufficient for externally imported artwork layouts. */
export function validateRenderableLayout(value: any, source?: any): string[] {
  const errors = validateLayout(value);
  if (!value || typeof value !== 'object') return errors;
  if (errors.length) return errors;
  const validNumber = (n: any) => typeof n === 'number' && Number.isFinite(n);
  const size = (s: any) => s && validNumber(s.width) && validNumber(s.height) && s.width > 0 && s.height > 0;
  const pixels = (s: any) => size(s) && Number.isSafeInteger(s.width) && Number.isSafeInteger(s.height);
  const point = (p: any) => p && validNumber(p.x) && validNumber(p.y);
  const polygonPoint = (p: any) => Array.isArray(p) ? p.length === 2 && p.every(validNumber) : point(p);
