      if (p?.assemblyOnly !== undefined && typeof p.assemblyOnly !== 'boolean') errors.push(`${s.stickerId} invalid assembly-only flag`);
      if (!p || typeof p.partId !== 'string' || parts.has(p.partId) || !asset(p.assetKey) || !size(p.sourceSize) || !point(p.offset) || !Number.isSafeInteger(p.layerIndex) || !dependencies(p.requiresAssetIds)) errors.push(`${s.stickerId} invalid render part`);
