/** Update denormalized gameplay metadata without changing source transforms/offsets. */
function refreshPlayMetadata(draft: GameLayout): void {
  let assemblyStep = 0;
  const placed = new Set<string>();
  const blocks = [...draft.geoBlocks].sort((a, b) => a.blockOrder - b.blockOrder);
  for (const block of blocks) {
    const members = draft.stickers.filter(sticker => sticker.geoBlock === block.blockId);
    const assembly: StickerPlacement[] = [];
    for (const level of AREA_LEVELS) {
      const pending = members.filter(sticker => sticker.areaLevel === level)
        .sort((a, b) => a.placementOrder - b.placementOrder);
      while (pending.length) {
        const index = pending.findIndex(sticker => (sticker.dependsOn ?? []).every(id => placed.has(id)));
        if (index < 0) throw new Error(`Unresolvable assembly stage in ${block.blockId}`);
        const sticker = pending.splice(index, 1)[0];
        placed.add(sticker.stickerId);
        assembly.push(sticker);
        sticker.assemblyStep = ++assemblyStep;
        sticker.blockAssemblyStep = assembly.length;
        sticker.blockOrder = block.blockOrder;
      }
    }
    block.requiredStickerIds = assembly.map(sticker => sticker.stickerId);
    block.assemblyOrder = [...block.requiredStickerIds as string[]];
    block.areaCounts = Object.fromEntries(AREA_LEVELS.map(level => [level,
      members.filter(sticker => sticker.areaLevel === level).length]));
    block.emptyStages = AREA_LEVELS.filter(level => !members.some(sticker => sticker.areaLevel === level));
    block.emptyStagePolicy = 'skip';
  }
}

