/** Display-space tolerance for the single already-selected sticker, not picking. */
export function placementSnapRadius(width: number, height: number, unit = 1): number {
  return Math.max(32 * unit, Math.min(70 * unit, Math.max(width, height) * .28));
}

const inside = (p: PlacementPoint, b: PlacementBoard): boolean =>
  p.x >= b.x && p.y >= b.y && p.x <= b.x + b.width && p.y <= b.y + b.height;

/** Each aim point owns its board check: a visible aligned paper can be released
 * with the finger outside the board. Transparent bounds alone never accept. */
export function acceptPlacementIntent(value: PlacementIntent): boolean {
  if (inside(value.finger, value.board) && value.opaqueFingerHit) return true;
  if (!inside(value.target, value.board)) return false;
  const near = (point: PlacementPoint): boolean => inside(point, value.board)
    && Math.hypot(point.x - value.target.x, point.y - value.target.y) <= value.snapRadius;
  return near(value.finger) || near(value.held);
