private startTour(): void {
  const current = this.session.getSnapshot().activeBlockId;
  const blocks = this.layout.geoBlocks.slice().sort((a: any, b: any) => a.blockOrder - b.blockOrder);
  const next = blocks[blocks.findIndex((b: any) => b.blockId === current) + 1];
  this.tour = { start: this.platform.now(), from: { ...this.camera }, overview: this.cameraForOverview(), to: next ? this.cameraForBlock(next) : this.cameraForOverview() };
  this.status = '这一角完成了，看看整座花园'; this.dirty = true;
}
private tick = (): void => {
  if (!this.running) return;
