  if (this.paste && now - this.paste.start >= 1550) {
    const paste = this.paste; this.paste = null;
    if (this.session.commitPlacement(paste.ticket)) {
      const state = this.session.getSnapshot();
      this.burst = { start: now, at: paste.to, final: state.phase === 'transitioning' || state.phase === 'completed' };
      this.page = 0; this.status = state.phase === 'completed' ? '花香与珠光，已经完整呈现' : '贴好了，给这一角一点星光';
    }
