  }
  if (this.burst && now - this.burst.start >= 1350) {
    this.burst = null;
    if (this.session.getSnapshot().phase === 'transitioning') this.startTour();
    else { this.status = this.session.getSnapshot().phase === 'completed' ? '整幅花园已经完成，可以保存画面' : '拿起下一张，继续还原这一角'; this.dirty = true; }
  }
